(async function(){'use strict';const title=document.getElementById('title');const sidebar=document.getElementById('sidebar');const nav=document.getElementById('nav');const menu=document.getElementById('menu');const signout=document.getElementById('signout');const kyb_pill=document.getElementById('kyb_pill');const metrics=document.getElementById('metrics');const quotes=document.getElementById('quotes');const partner=document.getElementById('partner');const route=document.getElementById('route');const amount=document.getElementById('amount');const estimate=document.getElementById('estimate');const note=document.getElementById('note');const request_status=document.getElementById('request_status');const history_body=document.getElementById('history_body');const add_director=document.getElementById('add_director');const director_list=document.getElementById('director_list');const add_owner=document.getElementById('add_owner');const owner_list=document.getElementById('owner_list');const documents_grid=document.getElementById('documents_grid');const submit_kyb=document.getElementById('submit_kyb');const declaration=document.getElementById('declaration');const document_status=document.getElementById('document_status');const api=window.LBPCorporate,c=api.client,access=await api.profile();if(!access){location.replace('login.html?next='+encodeURIComponent(location.pathname));return}const clientId=access.profile.client_id,userId=access.session.user.id;let deskQuotes=[],usdRate=0,onboarding=null,clientRow=null;const tabDefs=[['dashboard','Dashboard'],['request','New OTC Request'],['history','Request History'],['company','Company Profile'],['directors','Directors'],['owners','Beneficial Owners'],['funds','Source & Purpose'],['financial','Financial & Bank'],['documents','Documents & Declaration']];const money=(v,currency='IDR')=>new Intl.NumberFormat('en-US',{maximumFractionDigits:currency==='IDR'?0:8}).format(Number(v||0))+' '+currency;const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));function setTab(id){document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===id));title.textContent=tabDefs.find(x=>x[0]===id)[1];sidebar.classList.remove('open')}nav.innerHTML=tabDefs.map(([id,name],i)=>`<button data-tab="${id}" class="${i?'':'active'}">${name}</button>`).join('');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));menu.onclick=()=>sidebar.classList.toggle('open');signout.onclick=async()=>{await c.auth.signOut();location.replace('login.html')};
async function load(){const results=await Promise.all([c.from('corporate_clients').select('*').eq('id',clientId).single(),c.from('corporate_client_onboarding').select('*').eq('client_id',clientId).single(),c.from('partner_desks').select('id,display_name,status').eq('status','active').order('display_name'),c.from('partner_desk_quotes').select('*').order('quoted_at',{ascending:false}),c.from('asset_rates').select('asset_code,idr_rate').eq('asset_code','USD').maybeSingle(),c.from('corporate_otc_requests').select('*').eq('client_id',clientId).order('created_at',{ascending:false}),c.from('corporate_client_kyb_documents').select('*').eq('client_id',clientId)]);const err=[results[0],results[1],results[6]].find(x=>x.error)?.error;if(results[5].error){document.querySelector('#request_form button[type=submit],#request_form button').disabled=true;request_status.textContent='OTC request execution is awaiting activation. You can complete KYB onboarding now.';}if(err)throw err;clientRow=results[0].data;onboarding=results[1].data;usdRate=Number(results[4].data?.idr_rate||0);const latest=new Map();for(const q of results[3].data||[])if(!latest.has(q.partner_id))latest.set(q.partner_id,q);deskQuotes=(results[2].data||[]).map(d=>({...d,quote:latest.get(d.id)})).filter(x=>x.quote);render(results[5].data||[],results[6].data||[])}
function render(requests,docs){kyb_pill.textContent='KYB '+String(onboarding.kyb_status).toUpperCase();metrics.innerHTML=[['Company',clientRow.legal_name],['KYB Status',onboarding.kyb_status],['Active Requests',requests.filter(r=>!['settled','rejected','cancelled','expired'].includes(r.status)).length],['Partner Desks',deskQuotes.length]].map(([a,b])=>`<div class="card metric"><span class="eyebrow">${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('');quotes.innerHTML=deskQuotes.map(({display_name,quote})=>`<article class="card quote-card"><div class="quote-head"><div><h2>${esc(display_name)}</h2><span class="muted">Updated ${new Date(quote.quoted_at).toLocaleString()}</span></div><span class="pill">Available</span></div><div class="quote-row"><span><small class="quote-label">Buy</small><b class="quote-price">Rp ${money(quote.buy_price,'').trim()}</b></span><span><small class="quote-label">Sell</small><b class="quote-price">Rp ${money(quote.sell_price,'').trim()}</b></span><span><small class="quote-label">Spread</small><b class="quote-price">${quote.spread_percent}%</b></span><span><small class="quote-label">Fee</small><b class="quote-price">${quote.fee_percent}%</b></span><span><small class="quote-label">USDT</small><b class="quote-price">${money(quote.available_usdt,'USDT')}</b></span><span><small class="quote-label">IDR</small><b class="quote-price">Rp ${money(quote.available_idr,'').trim()}</b></span><button class="btn btn-secondary" data-choose="${quote.partner_id}">Choose</button></div></article>`).join('')||'<div class="notice">No current Partner Desk quote is available.</div>';document.querySelectorAll('[data-choose]').forEach(b=>b.onclick=()=>{partner.value=b.dataset.choose;setTab('request');calculate()});partner.innerHTML=deskQuotes.map(x=>`<option value="${x.id}">${esc(x.display_name)}</option>`).join('');history_body.innerHTML=requests.map(r=>`<tr><td class="mono">${esc(r.request_code)}</td><td>${new Date(r.created_at).toLocaleString()}</td><td>${esc(r.partner_id)}</td><td>${esc(r.route.replaceAll('_',' → '))}</td><td class="mono">${money(r.input_amount,r.input_asset)}</td><td class="mono">${money(r.estimated_output,r.output_asset)}</td><td><span class="pill">${esc(r.status)}</span></td></tr>`).join('')||'<tr><td colspan="7">No requests yet.</td></tr>';fillForms();renderDocuments(docs)}
function calculate(){const d=deskQuotes.find(x=>x.id===partner.value),q=d?.quote,a=Number(amount.value||0);if(!q||!a){estimate.value='';return}let gross=0,out='USDT';if(route.value==='IDR_USDT')gross=a/Number(q.sell_price);else if(route.value==='USD_USDT')gross=a/(Number(q.sell_price)/usdRate);else{gross=a*Number(q.buy_price);out='IDR'}estimate.value=money(gross*(1-Number(q.fee_percent||0)/100),out)}route.onchange=partner.onchange=amount.oninput=calculate;document.querySelector('#request_form').onsubmit=async e=>{e.preventDefault();request_status.textContent='Checking and reserving liquidity…';const{data,error}=await c.rpc('submit_corporate_otc_request',{p_partner_id:partner.value,p_route:route.value,p_input_amount:Number(amount.value),p_note:note.value||null});if(error){request_status.textContent=error.message;request_status.className='status full error'}else{request_status.textContent=`${data.request_code} submitted and liquidity reserved.`;request_status.className='status full success';await load();setTab('history')}};
function fillForms(){document.querySelectorAll('[data-save] input,[data-save] select').forEach(el=>{let v=el.name==='legal_name'?clientRow.legal_name:onboarding[el.name];el.value=Array.isArray(v)?v.join(', '):(v??'')});document.querySelectorAll('[data-save]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const payload={};new FormData(form).forEach((v,k)=>payload[k]=['source_of_funds','transaction_purpose','wealth_sources'].includes(k)?String(v).split(',').map(x=>x.trim()).filter(Boolean):v);delete payload.legal_name;delete payload.company_email;const{error}=await c.from('corporate_client_onboarding').update({...payload,updated_at:new Date().toISOString()}).eq('client_id',clientId);alert(error?error.message:'Saved successfully.');if(!error)Object.assign(onboarding,payload)})}
let directorCount=0;function directorBlock(){directorCount++;return`<form class="card section-card form-grid director-form"><h2 class="full">Director ${directorCount}</h2><input type="hidden" name="position_no" value="${directorCount}"><label><span>Full Name</span><input name="full_name" required></label><label><span>Date of Birth</span><input name="date_of_birth" type="date"></label><label><span>Place of Birth</span><input name="place_of_birth"></label><label><span>Nationality</span><input name="nationality"></label><label><span>ID Type</span><input name="identity_type"></label><label><span>ID Number</span><input name="identity_number"></label><label class="full"><span>Residential Address</span><input name="residential_address"></label><label><span>PEP</span><select name="is_pep"><option value="false">No</option><option value="true">Yes</option></select></label><button class="btn btn-primary full">Save Director</button></form>`}function bindDirectors(){document.querySelectorAll('.director-form').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(f));p.client_id=clientId;p.is_pep=p.is_pep==='true';const{error}=await c.from('corporate_client_directors').upsert(p,{onConflict:'client_id,position_no'});alert(error?error.message:'Director saved.')})}add_director.onclick=()=>{if(directorCount>=4)return alert('Maximum 4 directors.');director_list.insertAdjacentHTML('beforeend',directorBlock());bindDirectors()};director_list.innerHTML=directorBlock();bindDirectors();
let ownerCount=0;add_owner.onclick=()=>{ownerCount++;owner_list.insertAdjacentHTML('beforeend',`<form class="form-grid owner-form" style="margin-top:16px"><label><span>Full Name</span><input name="full_name" required></label><label><span>Ownership %</span><input name="ownership_percentage" type="number" step=".0001"></label><label><span>ID Number</span><input name="identity_number"></label><label><span>Nationality</span><input name="nationality"></label><label class="full"><span>Control Criteria Numbers</span><input name="control_criteria" placeholder="1, 2, 5"></label><button class="btn btn-primary full">Save Beneficial Owner</button></form>`);const f=owner_list.lastElementChild;f.onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(f));p.id=f.dataset.id||crypto.randomUUID();f.dataset.id=p.id;p.client_id=clientId;p.is_pep=p.is_pep==='true';p.is_representative=p.is_representative==='true';p.ownership_percentage=p.ownership_percentage?Number(p.ownership_percentage):null;p.control_criteria=String(p.control_criteria).split(',').map(Number).filter(Boolean);const{error}=await c.from('corporate_client_beneficial_owners').upsert(p);alert(error?error.message:'Beneficial owner saved.')}};add_owner.click();
const docTypes=[['director_id','Director ID',true],['beneficial_owner_id','Beneficial Owner ID',true],['deed_establishment','Deed of Establishment & Ministry Decree',true],['deed_amendment','Amendment & Ministry Decree (if any)',false],['nib','NIB',true],['npwp','Tax Identification Number',true],['sppkp','SPPKP',true],['statement_letter','Statement Letter',true],['nda','NDA Agreement',true]];function renderDocuments(docs){documents_grid.innerHTML=docTypes.map(([id,name,req])=>{const d=docs.find(x=>x.document_type===id);return`<div class="doc ${req?'required':''}"><h3>${esc(name)}</h3><p class="muted">${d?'Uploaded · '+esc(d.status):'Not uploaded'}</p><input type="file" data-doc="${id}" accept=".pdf,.jpg,.jpeg,.png"></div>`}).join('');documents_grid.querySelectorAll('input[type=file]').forEach(i=>i.onchange=async()=>{const f=i.files[0];if(!f)return;if(f.size>10485760)return alert('Maximum file size is 10 MB.');const path=`${userId}/${i.dataset.doc}/${Date.now()}-${f.name.replace(/[^a-zA-Z0-9._-]/g,'-')}`;const{error:up}=await c.storage.from('corporate-kyb').upload(path,f,{upsert:false});if(up)return alert(up.message);const{error}=await c.from('corporate_client_kyb_documents').upsert({client_id:clientId,user_id:userId,document_type:i.dataset.doc,storage_path:path,original_filename:f.name,mime_type:f.type,size_bytes:f.size,updated_at:new Date().toISOString()},{onConflict:'client_id,document_type'});alert(error?error.message:'Document uploaded.');if(!error)await load()})}submit_kyb.onclick=async()=>{if(!declaration.checked)return alert('Accept the declaration first.');const{error}=await c.from('corporate_client_onboarding').update({declaration_accepted:true,kyb_status:'submitted',submitted_at:new Date().toISOString()}).eq('client_id',clientId);document_status.textContent=error?error.message:'KYB submitted for review.';document_status.className=error?'status error':'status success';if(!error){onboarding.kyb_status='submitted';kyb_pill.textContent='KYB SUBMITTED'}};

function addPersonFields(form,owner=false){
 const extra=owner?[['date_of_birth','Date of Birth','date'],['place_of_birth','Place of Birth'],['identity_type','ID Type'],['residential_address','Residential Address']]:[];
 for(const [name,label,type='text'] of extra){const l=document.createElement('label');l.innerHTML='<span>'+label+'</span><input name="'+name+'" type="'+type+'">';form.insertBefore(l,form.querySelector('button'))}
 if(owner)for(const [name,label] of [['is_pep','Politically Exposed Person'],['is_representative','Beneficial Owner Representative']]){const l=document.createElement('label');l.innerHTML='<span>'+label+'</span><select name="'+name+'"><option value="false">No</option><option value="true">Yes</option></select>';form.insertBefore(l,form.querySelector('button'))}
}
const addOwnerHandler=add_owner.onclick;add_owner.onclick=()=>{addOwnerHandler();addPersonFields(owner_list.lastElementChild,true)};
addPersonFields(owner_list.firstElementChild,true);
async function hydratePeople(){
 const [d,b]=await Promise.all([c.from('corporate_client_directors').select('*').eq('client_id',clientId).order('position_no'),c.from('corporate_client_beneficial_owners').select('*').eq('client_id',clientId)]);
 if(d.error||b.error)throw d.error||b.error;
 if(d.data.length){directorCount=0;director_list.innerHTML='';for(const row of d.data){director_list.insertAdjacentHTML('beforeend',directorBlock());const f=director_list.lastElementChild;for(const el of f.elements)if(el.name&&row[el.name]!=null)el.value=String(row[el.name])}bindDirectors()}
 if(b.data.length){owner_list.innerHTML='';for(const row of b.data){add_owner.click();const f=owner_list.lastElementChild;f.dataset.id=row.id;for(const el of f.elements)if(el.name&&row[el.name]!=null)el.value=Array.isArray(row[el.name])?row[el.name].join(', '):String(row[el.name])}}
}
try{await load();await hydratePeople()}catch(e){document.querySelector('.content').innerHTML=`<div class="notice"><h2>Corporate Client data unavailable</h2><p>${esc(e.message)}</p></div>`}})();
